WITH parsed AS (SELECT id, customer_id, coupon_codes, items, ship_to, SIZE(attributes) AS num_attributes, attributes['utm_source'] AS utm_source, AGGREGATE(items, 0.0D, (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS cart_value, COALESCE(attributes['device'], 'unknown') AS device_or_default, COALESCE(ship_to.country, 'UNKNOWN') AS country_or_unknown FROM carts) SELECT CASE WHEN cart_value >= 1680 THEN 'PREMIUM' ELSE 'STANDARD' END AS cart_value_tier, PERCENTILE_APPROX(cart_value, ARRAY(0.25, 0.5, 0.75)) AS cart_value_quartiles, PERCENTILE_APPROX(num_attributes, ARRAY(0.25, 0.5, 0.75)) AS num_attributes_quartiles, COUNT(*) AS cnt, PERCENTILE_APPROX(num_attributes, 0.5) AS num_attributes_p50 FROM parsed GROUP BY CASE WHEN cart_value >= 1680 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING num_attributes_p50 < 1000000 ORDER BY cnt;
